attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying vec3 vN, vV; varying float vFuse;
    void main(){
      float u = uTime - aT - 0.10, L = length(aE - aO), tt = L/11.0;
      if (u < 0. || u > tt){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 d = (aE - aO)/L, up = vec3(0., 1., 0.), sd = normalize(cross(d, up)), vu = cross(sd, d);
      float f = u/tt, a = u*8.;
      vec3 C = mix(aO, aE, f) + vec3(0., min(2.2, .3*L)*4.*f*(1. - f), 0.);
      vec3 ax = normalize(sd + vu*.3); float ca = cos(a), sa = sin(a);
      vec3 p = position*ca + cross(ax, position)*sa + ax*dot(ax, position)*(1. - ca);
      vec3 nn = normal*ca + cross(ax, normal)*sa + ax*dot(ax, normal)*(1. - ca);
      vFuse = smoothstep(.17, .2, position.y);
      vec3 P = C + p; vN = nn; vV = normalize(cameraPosition - P);
      gl_Position = projectionMatrix*viewMatrix*vec4(P, 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange, uMoon; varying vec3 vN, vV; varying float vFuse;
    void main(){ vec3 n = normalize(vN); float l = .15 + .7*max(dot(n, uMoon), 0.), rim = pow(1. - abs(dot(n, normalize(vV))), 3.);
      gl_FragColor = vec4(vec3(.09, .085, .08)*l + uOrange*rim*.35 + mix(uOrange, uGold, .7)*vFuse*3., 1.); }   // dark iron, lit fuse

